import test from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { readFileSync } from 'node:fs';
const bundle = readFileSync(new URL('../lib/client.js', import.meta.url), 'utf8');
test('built output is current and generated from tracked sources', () => {
  const read = path => readFileSync(new URL('../' + path, import.meta.url), 'utf8');
  const expected = '// Generated by node scripts/build.mjs; edit src instead.\n(() => {\n' + read('src/core.js').replaceAll('export ', '') + '\n' + read('src/calendar.js').replaceAll('export ', '') + '\n' + read('src/client.js').replace(/^import .*;\n/gm, '') + '\n})();\n';
  assert.equal(bundle, expected);
});
test('client factory loads, injects declared slot, renders only allowed label and cleans up', () => {
  let definition, component, disposer;
  let states = [], refs = [], effects = [], cursor = 0, refCursor = 0;
  let intervals = new Map(), timeouts = new Map(), listeners = new Set();
  let seq = 0;
  const React = {
    Fragment: 'fragment', createElement: (type, props, ...children) => ({ type, props, children }),
    useRef(value) { return refs[refCursor++] ??= { current: value }; },
    useState(value) { const i = cursor++; if (states[i] === undefined) states[i] = value; return [states[i], value => { states[i] = typeof value === 'function' ? value(states[i]) : value; }]; },
    useEffect(fn) { effects.push(fn); }
  };
  vm.runInNewContext(bundle, {
    window: { __ModuleLoader__: { load(value) { definition = value; } } },
    document: { addEventListener(_, fn) { listeners.add(fn); }, removeEventListener(_, fn) { listeners.delete(fn); } },
    Date, Set, Object, Number, TypeError,
    setInterval(fn) { const id = ++seq; intervals.set(id, fn); return id; }, clearInterval(id) { intervals.delete(id); },
    setTimeout(fn) { const id = ++seq; timeouts.set(id, fn); return id; }, clearTimeout(id) { timeouts.delete(id); }
  });
  assert.equal(definition.id, 'dsh-feng-gu-lite');
  const plugin = definition.factory(name => { assert.equal(name, 'react'); return React; });
  assert.equal(JSON.stringify(plugin.inject), '["slots"]');
  plugin.apply({ slots: { inject(name, fn) { assert.equal(name, 'conversation.composer.dock'); disposer = fn(); }, register(spec, comp) { assert.equal(spec.name, 'conversation.composer.dock'); component = comp; return 'dispose-token'; } } });
  assert.equal(disposer, 'dispose-token');
  component({ useSession() {} });
  const stop = effects.shift()();
  assert.equal(intervals.size, 1); assert.equal(listeners.size, 1);
  // Force a known period to inspect the actual render tree without selecting a calendar policy.
  states[0] = { period: 'peak', pulse: true }; cursor = 0; refCursor = 0;
  const tree = component({ useSession() {} });
  assert.equal(tree.type, 'fragment');
  assert.equal(tree.children[1].children[1], '梁文峰');
  assert.equal(tree.children[2].props.role, 'status');
  assert.ok(tree.children[0].children[0].includes('@media(prefers-reduced-motion:reduce)'));
  assert.equal(tree.children[1].props.onClick, undefined);
  states[0] = { period: 'idle', pulse: false }; cursor = 0; refCursor = 0;
  const idle = component({ useSession() {} });
  assert.equal(idle.children[1].children[1], '梁文谷'); assert.equal(idle.children[2], null);
  states[0] = { period: 'unknown', pulse: false }; cursor = 0; refCursor = 0;
  const unknown = component({ useSession() {} });
  assert.equal(unknown.children[1].children[1], '时段待确认');
  assert.equal(unknown.children[2], null);
  stop(); assert.equal(intervals.size, 0); assert.equal(listeners.size, 0); assert.equal(timeouts.size, 0);
});
test('server export is no-op and bundled client has no account/network capabilities', async () => {
  const plugin = await import('../lib/index.js'); assert.equal(plugin.apply(), undefined);
  assert.doesNotMatch(bundle, /\bfetch\s*\(|XMLHttpRequest|WebSocket|credentials|process\.env|localStorage|sessionStorage/);
});
